l_inner.code:
SELECT c.name, o.total
FROM customers AS c
JOIN orders AS o ON o.customer_id = c.id;

l_left.code:
SELECT c.name, o.total
FROM customers AS c
LEFT JOIN orders AS o ON o.customer_id = c.id;

l_right.code:
SELECT c.name, o.total
FROM customers AS c
RIGHT JOIN orders AS o ON o.customer_id = c.id;

l_full.code:
SELECT c.name, o.total
FROM customers AS c
FULL OUTER JOIN orders AS o ON o.customer_id = c.id;
